?><!doctype html><html lang="fa" dir="rtl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>پنل | Etebarami SMS Gateway</title><style>
:root{--bg:#f3f6fb;--ink:#182238;--muted:#69778b;--blue:#1769e0;--line:#e1e7ef}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:14px Tahoma,Arial;color:var(--ink)}header{background:white;padding:15px 4vw;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line)}main{max-width:1200px;margin:25px auto;padding:0 18px}.layout{display:grid;grid-template-columns:210px 1fr;gap:20px}nav,.card{background:white;border:1px solid var(--line);border-radius:14px;padding:17px}nav a{display:block;padding:10px;text-decoration:none;color:var(--ink);border-radius:8px}nav a:hover{background:#edf4ff;color:var(--blue)}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:12px}.metric{padding:18px;background:white;border:1px solid var(--line);border-radius:12px}.metric strong{display:block;font-size:24px;margin-top:10px}.content{margin-top:16px}.row{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:12px}input,textarea,select{width:100%;padding:11px;border:1px solid #ccd5e2;border-radius:8px;margin:6px 0 14px;font:inherit}textarea{min-height:110px}button,.btn{display:inline-block;background:var(--blue);color:white;border:0;border-radius:8px;padding:10px 15px;text-decoration:none;cursor:pointer;font:inherit}.secondary{background:#52647d}.danger{background:#bb3546}.notice{padding:12px;background:#edf7f1;border-radius:9px;margin-bottom:14px}.muted{color:var(--muted)}table{width:100%;border-collapse:collapse;background:white}th,td{text-align:right;border-bottom:1px solid var(--line);padding:10px}td{font-size:13px}.tablewrap{overflow:auto}.code{font:20px monospace;letter-spacing:3px;color:#08754d}.actions{display:flex;gap:8px;flex-wrap:wrap}@media(max-width:760px){.layout{grid-template-columns:1fr}nav{display:flex;overflow:auto;gap:4px;padding:8px}nav a{white-space:nowrap}.content{margin-top:8px}}
