<?php elseif($page==='logs'): ?><h1>لاگ سیستم</h1><div class="card"><div class="tablewrap"><table><tr><th>زمان</th><th>مدیر</th><th>عملیات</th><th>جزئیات</th><th>IP</th></tr><?php foreach($pdo->query('SELECT * FROM audit_logs ORDER BY id DESC LIMIT 200') as $l):?><tr><td><?=e($l['created_at'])?></td><td><?=e((string)$l['admin_id'])?></td><td><?=e($l['action'])?></td><td><?=e($l['details'])?></td><td><?=e($l['ip'])?></td></tr><?php endforeach?></table></div></div><div class="card content"><h3>رویدادهای Telegram</h3><div class="tablewrap"><table><tr><th>زمان</th><th>رویداد</th><th>نتیجه</th><th>جزئیات</th></tr><?php foreach($pdo->query('SELECT * FROM telegram_logs ORDER BY id DESC LIMIT 100') as $t):?><tr><td><?=e($t['created_at'])?></td><td><?=e($t['event_type'])?></td><td><?=e($t['result'])?></td><td><?=e($t['detail'])?></td></tr><?php endforeach?></table></div></div><?php endif ?></section></div></main><script>const ts=document.getElementById('templateSelect');if(ts)ts.addEventListener('change',()=>{const b=document.getElementById('body');if(b&&ts.value)b.value=ts.value;b&&b.dispatchEvent(new Event('input'))});const b=document.getElementById('body');if(b)b.addEventListener('input',()=>{const n=b.value.length,uni=/[^\x00-\x7F]/.test(b.value),size=uni?70:160,seg=n<=size?1:Math.ceil(n/(uni?67:153));document.getElementById('smsInfo').textContent=`${n} نویسه · ${uni?'Unicode':'GSM-7 تقریبی'} · حدود ${seg} بخش`});</script></html>
